/* a muted object keeps time and plays nothing; the moment it is muted its sounding notes are cut */
setInterval(() => {
  for (const rt of running) {
    const ow = blocks.find(x => x.id === rt.b.owner);
    if (ow?.data.retired) continue;
    const mu = !!ow && isMuted(ow);
    if (mu && !rt.seq.muted) rt.seq.rack?.silence?.();
    rt.seq.muted = mu;
    rt.seq.schedule();
  }
}, 25);

