/* the cell, or strip, under a point: { k (step in the line), row | strip } */
function hit(b, rt, G, e) {
  if (e.x < G.x0 || e.x >= G.x0 + G.w || e.y < G.gy0) return null;
  const k = page(b, rt) * PAGE + Math.min(PAGE - 1, Math.floor((e.x - G.x0) / G.cw));
  if (e.y >= G.sy) { const i = Math.floor((e.y - G.sy) / STRIP_H); return i < STRIPS.length ? { k, strip: i } : null; }
  if (e.y >= G.sy - 4) return null;
  return { k, row: Math.max(0, Math.min(G.R - 1, G.R - 1 - Math.floor((e.y - G.gy0) / G.rh))) };
}

function apply(b, rt, h, mode) {
  const s = rt.seq, st = s.steps[h.k];
  if (h.strip === undefined) {
    if (mode.kind === 'clear') st.rest = true;
    else { st.rest = false; st.note = rowNote(s.scale, s.root, base(b), h.row); const key = h.k + ':' + st.note; if (rt.heard1 !== key) { rt.heard1 = key; audition(b, rt, st); } }      // painting across rows sounds each new note once
  } else if (!st.rest) {
    if (h.strip === 0) st.accent = mode.value; else if (h.strip === 1) st.slide = mode.value;
    else if (h.strip === 2) st.gate = mode.value; else if (h.strip === 3) st.prob = mode.value;
    else if (h.strip === 4) { if (mode.value) st.nudge = mode.value; else delete st.nudge; }
    else if (mode.value) st.seventh = true; else delete st.seventh;
  }
