messages.content:
/* the melody pane: the pianoroll of a 303-style line, 16, 32 or 64 steps long, one pitch per step.
 *
 * It is a track of the sequencer view (a hidden pane owned by a VCO or a MIDI synth) and plays that object with the
 * transport. The grid shows one bar (16 steps) at a time on the shared step columns, so it lines up with the drum grid;
 * the page tabs move through the bars and `Follow` keeps the playing bar on screen.
 *
 *   Header 1  Len (16/32/64; a longer line starts as a repeat)  Root  Scale  Oct -/+ (the window of rows)
 *   Header 2  pages  Follow  rotate < >  transpose -1 +1  Dice (a new line within the scale; on a generated pattern
 *             the next take of its style, over the shown phrase's chords)  Aid  the bar's chord
 *   Aid       rows of the chord of the shown bar (the SONG view's chord row) light up: its root and tones in yellow, the
 *             key's blue note in blue; the other rows stay as they are. Off: plain rows
 *   Grid      rows are the scale's notes over one octave and the root above; touch a cell to set the note, touch the note
 *             again to clear it; drag across columns to paint, up and down to move the note
 *   Strips    ACC accent (louder, opens the filter), SLD slide (glides, holds the note), GATE (short/normal/long),
 *             PROB (the chance the step plays); touch toggles or cycles, drag paints
 *
 * Notes outside the window show as an arrow at its edge. The line lives in the song store (kind 'melody').
 */

import { Harmony } from '../../vendor/qjs-sound/tonnetz/lib/harmony.js';
import { registerBlock, changed, blocks, removeBlock, innerOf, pg, toggleFull } from '../playground.js';
import { mirrorNote } from '../midi-mirror.js';
import { phone } from '../touch.js';
import { chordEditor } from './chord-editor.js';
import { chordName } from '../lattice.js';
import { createMelody, LENGTHS, SCALES, NOTE_NAMES, rowNote, noteRow, emptyStep, fromDegrees } from '../acid/melody.js';
import { stepCols } from '../step-cols.js';
import { transport } from '../transport.js';
import { store } from '../store.js';
import { deviceOf } from '../midi-devices.js';
import { isMuted } from '../mute.js';
import { acidOf } from './acid.js';
import { hwOf } from '../hw.js';
import { paneChain, claimCell, song, regenerate } from '../songplay.js';
import { chordAt, pcRole } from '../arrange.js';
import { ROLE_RGB } from '../look.js';

const PAGE = 16, CHIP_H = 40, HDR = 2 * CHIP_H + 14, STRIP_H = phone() ? 13 : 20, STRIPS = ['ACC', 'SLD', 'GATE', 'PROB', 'NUDGE', '7TH'];
const GATES = [0.3, 0.6, 0.9], PROBS = [1, 0.75, 0.5, 0.25];
/* a tap on the NUDGE strip cycles: on the grid, a third late (a triplet), a sixth late (a shuffle), half late; then early */
const NUDGES = [0, 1 / 3, 1 / 6, 0.5, -1 / 6, -1 / 3, -0.5];
const GUTTER_W = 64;                     // piano gutter width in expanded view
const EXP_OCT = 3;                       // 3 octaves = 36 semitones + top C = 37 rows
const EXP_ROWS = EXP_OCT * 12 + 1;       // 37
const rts = new WeakMap(), running = new Set();
const PLAYABLE = x => x.type === 'acid' || x.type === 'vco' || x.type === 'keys' || x.type === 'organ' || x.type === 'guitar' || x.type === 'flute' || x.type === 'fm' || x.type === 'msynth' || x.type === 'mfluid' || x.type === 'mmorph';
const hwInstrument = a => ({ id: 'msynth', label: 'MIDI', start: () => hwOf(a).start(), get rack() { return hwOf(a).rack; }, stop: () => hwOf(a).stop() });
/* the objects that module.js owns (VCO, KEYS, ORGAN) hand in their instrument here, so the two files do not import each other */
const instruments = {};
export const registerInstrument = (type, make) => { instruments[type] = make; };
const instrumentOf = a => (instruments[a.type] ? instruments[a.type](a) : a.type === 'msynth' || a.type === 'mfluid' || a.type === 'mmorph' ? hwInstrument(a) : acidOf(a));
const nameOf = a => a.type === 'mfluid' ? (deviceOf(a)?.id === 'mt32' ? 'MT-32 ' : 'FluidSynth ') + a.id : ({ vco: 'VCO ', msynth: 'MIDI synth ', mmorph: 'Morph ', keys: 'KEYS ', organ: 'ORGAN ', guitar: 'GUITAR ', flute: 'FLUTE ', fm: 'FM ' }[a.type] || 'Acid ') + a.id;
const target = b => blocks.find(x => x.id === b.data.target && PLAYABLE(x)) || null;

/* expanded when this pane is full-screen or focused in SEQ */
const expanded = b => pg.full === b.id || (pg.seq && pg.seqFocus === b.id);

/* the lowest MIDI note of the expanded window: C of (base + 1) octave */
const expBaseNote = b => 12 * (base(b) + 1);

/* the first line a new track gets: a C minor riff with a slide and two accents */
const riff = () => {
  const n = [36, 36, 48, 36, 39, 36, 43, 36, 36, 36, 48, 41, 39, 36, 34, 36];
  return n.map((note, k) => ({ ...emptyStep(note), rest: k % 4 === 1 && k !== 5, accent: k === 2 || k === 10, slide: k === 12 }));
};

/* the pattern in the store; a track that used the old 16-step pane (b.data.from = its pattern id) converts that line */
function ensurePattern(b) {
  if (store.hasPattern(b.data.pat) || b.data.track) return;          // a song track gets its patterns from the song
  const m = createMelody({ now: () => 0 });
  const old = b.data.from && store.pattern(b.data.from);
  if (old?.steps) { const h = new Harmony(); h.octave = b.data.base ?? 2; m.steps = fromDegrees(old.steps, d => h.pitchOf(d)); } else m.steps = riff();
  delete b.data.from;
  b.data.pat = store.newPattern('melody', m.getState());
  changed();
}

function runtime(b) {
  let rt = rts.get(b);
  if (rt) return rt;
  const seq = createMelody({ now: () => seq.rack?.ctx.currentTime ?? 0 });
  ensurePattern(b);
  seq.setState(store.pattern(b.data.pat));
  seq.bpm(transport.bpm);
  /* an arrangement (its row of the song, or an old saved chain): the pane follows its phrases, b.data.pat = the one playing;
     a silent cell plays an empty bar in the pane's scale */
  const resolve = id => (id ? store.pattern(id) : { steps: Array.from({ length: PAGE }, () => emptyStep(48)), root: seq.root, scale: seq.scale });
  seq.onPhrase = (pos, e) => { b.data.pat = e.pat; b.data.pos = pos; };
  const list = paneChain(b);
  if (list) { seq.chain(list, resolve); seq.seek(transport.barAt()); }
  store.on(e => { if (e.type === 'song' && b.data.track && rts.get(b) === rt) seq.rechain(paneChain(b), resolve, t => transport.barAt(t)); });
  rt = { b, seq, step: -1, touches: new Map(), chips: [], last: -1, pulse: 0 };
  rt.leave = transport.add({
    async start(t) {
      const ow = blocks.find(x => x.id === b.owner);
      if (ow?.data.retired) return;
      const a = target(b) || blocks.find(PLAYABLE);
      if (!a) return;
      b.data.target = a.id;
      const be = instrumentOf(a);
      await be.start();
      be.setTempo?.(transport.bpm);
      seq.rack = be.rack;
      seq.mirror = a.type === 'msynth' || a.type === 'mfluid' || a.type === 'mmorph' ? null : (midi, vel, t0, dur) => mirrorNote(nameOf(a).trim(), midi, vel, t0, dur);
      seq.start(t, transport.stepDur());
      running.add(rt);
    },
    stop() { seq.stop(); running.delete(rt); rt.step = -1; },
    bpm(v) { seq.bpm(v); const a = target(b); if (a) instrumentOf(a).setTempo?.(v); },
    swing(v) { seq.swing = v; },
    seek(bar, t) { seq.seek(bar, t); },
  });
  rts.set(b, rt);
  return rt;
}

/* a muted object keeps time and plays nothing; the moment it is muted its sounding notes are cut */
setInterval(() => {
  for (const rt of running) {
    const ow = blocks.find(x => x.id === rt.b.owner);
    if (ow?.data.retired) continue;
    const mu = !!ow && isMuted(ow);
    if (mu && !rt.seq.muted) rt.seq.rack?.silence?.();
    rt.seq.muted = mu;
    rt.seq.schedule();
  }
}, 25);

/* an edit goes to the store; on a silent cell of the song it makes the pattern there */
const keep = (b, rt) => { if (!store.hasPattern(b.data.pat) && b.data.track) claimCell(b, 'melody', rt.seq.getState()); else store.setPattern(b.data.pat, rt.seq.getState()); changed(); };
export const melodyRt = runtime;
export const melodyCommit = b => keep(b, runtime(b));

/* advances the playhead to what has sounded; the pane and its object both call it every frame.
 * rt.step and rt.stepT: the step sounding and when it began; rt.heard { midi, t }: the last note */
export function melodyTick(b) {
  const rt = runtime(b), seq = rt.seq;
  if (seq.rack) { const q = seq.stepQueue, ct = seq.rack.ctx.currentTime; while (q.length && q[0].t <= ct) { const e = q.shift(); rt.step = e.k; rt.stepT = e.t; if (e.note) { rt.pulse = 1; rt.heard = { midi: e.midi, t: e.t, k: e.k }; } } }
  rt.pulse *= 0.9;
  return rt;
}

const base = b => b.data.base ?? 2;
const pages = rt => rt.seq.len / PAGE;
const page = (b, rt) => Math.min(pages(rt) - 1, (b.data.follow !== false && rt.seq.running && rt.step >= 0 ? Math.floor(rt.step / PAGE) : b.data.page) | 0);
const rowsOf = rt => SCALES[rt.seq.scale].notes.length + 1;

/* expanded: 37 rows (3 octaves + top C), compact: scale rows + root above.
 * r=0 is the BOTTOM row (as in compact view). expRowNote/expNoteRow match that.
 */
const expRows = () => EXP_ROWS;
const expRowNote = (b, rt, r) => expBaseNote(b) + r;
const expNoteRow = (b, rt, note) => {
  const n = note - expBaseNote(b);
  return n < 0 || n >= EXP_ROWS ? -1 : n;
};
/* white-key rows (pc 0,2,4,5,7,9,11) are light, black-key rows (1,3,6,8,10) are dark */
const isBlackRow = (note) => { const pc = ((note % 12) + 12) % 12; return pc === 1 || pc === 3 || pc === 6 || pc === 8 || pc === 10; };

function geom(b, rt) {
  const isExp = expanded(b);
  const { x0, w } = stepCols(b);
  const R = isExp ? expRows() : rowsOf(rt);
  const gy0 = b.y + HDR;
  const stripsH = (!isExp || b.data.drawer !== false) ? STRIPS.length * STRIP_H : 0;
  const sy = b.y + b.h - 8 - stripsH;
  const rh = (sy - gy0 - 4) / R;
  const gutter = isExp ? GUTTER_W : 0;
  return { x0: x0 + gutter, w: w - gutter, cw: (w - gutter) / PAGE, gy0, sy, rh, R, gutter };
}

/* the chips of both header rows */
function chips(b, rt) {
  const s = rt.seq, p = page(b, rt), out = [];
  let x = b.x + 8, y = b.y + 6;
  const add = (id, label, w, on = false) => { out.push({ id, label, x, y, w, h: CHIP_H, on }); x += w + 6; };
  add('len', 'Len ' + s.len, 96); add('root', 'Root ' + NOTE_NAMES[s.root], 96); add('scale', SCALES[s.scale].name, 130);
  add('odn', '-', CHIP_H); add('oct', 'Oct ' + base(b), 78); add('oup', '+', CHIP_H);
  x = b.x + 8; y += CHIP_H + 4;
  for (let i = 0; i < pages(rt); i++) add('page' + i, String(i + 1), 44, i === p);
  add('follow', 'Follow', 90, b.data.follow !== false);
  add('rotl', '<', 44); add('rotr', '>', 44); add('trdn', '-1', 50); add('trup', '+1', 50);
  add('dice', song()?.gens?.[b.data.pat] ? song().gens[b.data.pat].style + ' ' + song().gens[b.data.pat].seed : 'Dice', song()?.gens?.[b.data.pat] ? 116 : 70);
  if (['keys', 'organ'].includes(target(b)?.type)) add('chord', 'Chord', 76, !!b.data.chordMode);       // a tap on a step opens the Tonnetz chord editor
  add('aid', 'Aid', 64, b.data.aid !== false); add('trip', 'Trip', 64, s.steps.some(x => x.nudge));
  /* expanded view: Expand chip toggles full screen / SEQ focus */
  if (pg.seq) add('expand', 'Expand', 76, pg.seqFocus === b.id);
  else add('expand', 'Expand', 76, pg.full === b.id);
  /* drawer toggle for strips (expanded only) */
  if (expanded(b)) add('lanes', 'Lanes', 76, b.data.drawer !== false);
  return out;
}

/* the song bar the shown page is: the bar playing (or where play starts), moved by the page against the playing one */
function shownBar(b, rt) {
  const cur = Math.floor(transport.barAt() + 1e-6), bars = rt.seq.len / PAGE;
  const at = rt.seq.running && rt.step >= 0 ? Math.floor(rt.step / PAGE) : ((cur % bars) + bars) % bars;
  return Math.max(0, cur - at + page(b, rt));
}

/* the theory of the shown bar: its chord (or null) and the key (the song's, else the pane's own root and scale) */
function theory(b, rt) {
  const sg = song(), bar = shownBar(b, rt);
  return { bar, chord: sg ? chordAt(sg, bar) : null, key: sg?.key || { root: rt.seq.root, scale: rt.seq.scale } };
}

function draw(g, b) {
  const rt = melodyTick(b), s = rt.seq, G = geom(b, rt), p = page(b, rt), t = target(b);
  const isExp = expanded(b);
  const N = SCALES[s.scale].notes;
  g.fillStyle = 'rgba(0,0,0,0.82)'; g.fillRect(b.x, b.y, b.w, b.h);
  g.textBaseline = 'middle'; g.textAlign = 'center'; g.font = '600 17px system-ui, sans-serif';
  rt.chips = chips(b, rt);
  for (const c of rt.chips) {
    g.fillStyle = c.on ? '#4de1ff' : 'rgba(255,255,255,0.14)'; g.beginPath(); g.roundRect(c.x, c.y, c.w, c.h, 10); g.fill();
    g.fillStyle = c.on ? '#000' : '#fff'; g.fillText(c.label, c.x + c.w / 2, c.y + c.h / 2);
  }
  g.textAlign = 'right'; g.font = '500 16px system-ui, sans-serif'; g.fillStyle = 'rgba(255,255,255,0.6)';
  g.fillText(t ? '-> ' + nameOf(t) : 'no instrument linked', b.x + b.w - 12, b.y + 6 + CHIP_H / 2);
  const aid = b.data.aid !== false ? theory(b, rt) : null, last = rt.chips[rt.chips.length - 1];
  if (aid) {
    g.textAlign = 'left'; g.font = '700 20px system-ui, sans-serif'; g.fillStyle = aid.chord ? `rgb(${ROLE_RGB.root})` : 'rgba(255,255,255,0.4)';
    g.fillText(aid.chord ? aid.chord.name : 'no chord', last.x + last.w + 12, last.y + CHIP_H / 2);
    g.font = '500 13px system-ui, sans-serif'; g.fillStyle = 'rgba(255,255,255,0.5)'; g.fillText('bar ' + (aid.bar + 1), last.x + last.w + 110, last.y + CHIP_H / 2);
  }

  /* piano gutter in expanded view */
  if (isExp) drawGutter(g, b, G, rt);

  /* rows */
  for (let r = 0; r < G.R; r++) {
    const y = G.gy0 + (G.R - 1 - r) * G.rh;
    let note, isRoot, role, rgb;
    if (isExp) {
      note = expRowNote(b, rt, r);
      isRoot = (note % 12) === s.root;
      role = aid ? pcRole(note % 12, aid.chord, aid.key, SCALES) : null;
      rgb = ROLE_RGB[role];
    } else {
      note = rowNote(s.scale, s.root, base(b), r);
      isRoot = r % N.length === 0;
      role = aid ? pcRole(note % 12, aid.chord, aid.key, SCALES) : null;
      rgb = ROLE_RGB[role];
    }
    /* row shading: expanded = white/black keys + scale tint, compact = scale rows only */
    if (isExp) {
      const black = isBlackRow(note);
      g.fillStyle = black ? 'rgba(255,255,255,0.07)' : 'rgba(255,255,255,0.03)';
      g.fillRect(G.x0, y, G.w, G.rh - 1);
      const deg = (note - s.root + 120) % 12;                                // the scale's tones in amber, the root brighter
      if (!role && N.includes(deg)) { g.fillStyle = deg === 0 ? 'rgba(234,179,8,0.22)' : 'rgba(234,179,8,0.09)'; g.fillRect(G.x0, y, G.w, G.rh - 1); }
      if (role) {
        const a = role === 'chord' ? 0.13 : role === 'root' ? 0.25 : 0.2;
        g.fillStyle = `rgba(${rgb},${a})`;
        g.fillRect(G.x0, y, G.w, G.rh - 1);
      }
      if (rgb) { g.fillStyle = `rgb(${rgb})`; g.fillRect(G.x0, y, 3, G.rh - 1); }
    } else {
      g.fillStyle = rgb ? `rgba(${rgb},${role === 'chord' ? 0.13 : 0.2})` : isRoot ? 'rgba(255,255,255,0.1)' : 'rgba(255,255,255,0.035)';
      g.fillRect(G.x0, y, G.w, G.rh - 1);
      if (rgb) { g.fillStyle = `rgb(${rgb})`; g.fillRect(G.x0, y, 3, G.rh - 1); }
    }
    /* row label (note name + octave) */
    g.fillStyle = rgb ? `rgb(${rgb})` : isRoot ? '#d8def0' : 'rgba(216,222,240,0.5)';
    g.textAlign = 'right'; g.font = `${Math.round(Math.min(13, G.rh * 0.6))}px system-ui, sans-serif`;
    const label = isExp ? NOTE_NAMES[note % 12] + (Math.floor(note / 12) - 1)
      : NOTE_NAMES[rowNote(s.scale, s.root, base(b), r) % 12] + (Math.floor(rowNote(s.scale, s.root, base(b), r) / 12) - 1);
    g.fillText(label, G.x0 - 6, y + G.rh / 2);
  }
  /* vertical grid lines */
  g.strokeStyle = 'rgba(255,255,255,0.06)'; g.lineWidth = 1; g.beginPath();
  const gridBottom = isExp && b.data.drawer !== false ? G.sy : G.sy + STRIPS.length * STRIP_H;
  for (let k = 0; k <= PAGE; k++) { const x = Math.round(G.x0 + k * G.cw) + 0.5; g.moveTo(x, G.gy0); g.lineTo(x, gridBottom); }
  g.stroke();
  /* playhead */
  if (s.running && rt.step >= p * PAGE && rt.step < (p + 1) * PAGE) {
    g.fillStyle = 'rgba(255,255,255,0.08)'; g.fillRect(G.x0 + (rt.step - p * PAGE) * G.cw, G.gy0, G.cw, gridBottom - G.gy0);
  }
  /* steps */
  for (let k = 0; k < PAGE; k++) {
    const st = s.steps[p * PAGE + k], x = G.x0 + k * G.cw;
    if (!st.rest) {
      let row;
      if (isExp) {
        row = expNoteRow(b, rt, st.note);
      } else {
        row = noteRow(s.scale, s.root, base(b), st.note);
      }
      const off = row < 0 || row >= G.R;
      const ry = off ? (row < 0 ? G.gy0 + G.rh / 2 : G.gy0 + (G.R - 0.5) * G.rh)
        : G.gy0 + (G.R - 1 - row) * G.rh;
      g.globalAlpha = 0.45 + 0.55 * st.prob;
      g.fillStyle = st.accent ? '#ff5ec8' : '#39d5ff';
      g.fillRect(x + 1, ry + 1, G.cw - 2, G.rh - 3);
      if (st.slide) { g.fillStyle = '#7dffb0'; g.fillRect(x + G.cw - 5, ry + 1, 9, G.rh - 3); }
      g.globalAlpha = 1;
      if (st.chord) { g.fillStyle = '#000'; g.textAlign = 'center'; g.font = `700 ${Math.round(Math.min(11, G.rh * 0.6))}px system-ui, sans-serif`; g.fillText(chordName(st.chord, !!st.seventh), x + G.cw / 2, ry + G.rh / 2); }
      if (off) { g.fillStyle = '#fff'; g.beginPath(); const up = row < 0; g.moveTo(x + G.cw / 2, ry + (up ? -4 : 4)); g.lineTo(x + G.cw / 2 - 6, ry + (up ? 4 : -4)); g.lineTo(x + G.cw / 2 + 6, ry + (up ? 4 : -4)); g.fill(); }
      if (row < 0 && !isExp) { g.strokeStyle = '#fff'; g.lineWidth = 2; g.strokeRect(x + 1.5, ry + 1.5, G.cw - 3, G.rh - 4); }
    }
    /* strips (only in compact, or expanded with drawer open) */
    if (!isExp || b.data.drawer !== false) {
      for (let i = 0; i < STRIPS.length; i++) {
        const y = G.sy + i * STRIP_H;
        g.fillStyle = 'rgba(255,255,255,0.05)'; g.fillRect(x + 1, y + 1, G.cw - 2, STRIP_H - 2);
        if (st.rest) continue;
        if (i === 0 && st.accent) { g.fillStyle = '#ff5ec8'; g.fillRect(x + 1, y + 1, G.cw - 2, STRIP_H - 2); }
        if (i === 1 && st.slide) { g.fillStyle = '#7dffb0'; g.fillRect(x + 1, y + 1, G.cw - 2, STRIP_H - 2); }
        if (i === 2) { g.fillStyle = '#ffd24d'; g.fillRect(x + 1, y + 1, (G.cw - 2) * st.gate, STRIP_H - 2); }
        if (i === 3 && st.prob < 1) { g.fillStyle = '#b48cff'; g.fillRect(x + 1, y + 1, (G.cw - 2) * st.prob, STRIP_H - 2); }
        if (i === 4 && st.nudge) { g.fillStyle = '#ff9a3c'; const m = x + G.cw / 2, w = (G.cw - 2) * st.nudge; g.fillRect(w > 0 ? m : m + w, y + 1, Math.abs(w), STRIP_H - 2); }
        if (i === 5 && st.seventh) { g.fillStyle = '#ffd24d'; g.fillRect(x + 1, y + 1, G.cw - 2, STRIP_H - 2); }
      }
    }
  }
  /* strip labels (only when strips are drawn) */
  if (!isExp || b.data.drawer !== false) {
    g.textAlign = 'right'; g.font = '600 11px system-ui, sans-serif'; g.fillStyle = 'rgba(255,255,255,0.6)';
    STRIPS.forEach((l, i) => g.fillText(l, G.x0 - 6, G.sy + i * STRIP_H + STRIP_H / 2));
  }
  chordEditor.draw(g, b);
}

/* draw the piano gutter (left 64px) in expanded view */
function drawGutter(g, b, G, rt) {
  const s = rt.seq;
  const gutterX = b.x;
  const gutterY = G.gy0;
  const gutterH = G.sy - G.gy0;
  g.save();
  g.beginPath(); g.rect(gutterX, gutterY, GUTTER_W, gutterH); g.clip();
  /* white keys */
  for (let r = 0; r < G.R; r++) {
    const y = G.gy0 + (G.R - 1 - r) * G.rh;
    const note = expRowNote(b, rt, r);
    const pc = note % 12;
    const isWhite = ![1, 3, 6, 8, 10].includes(pc);
    if (!isWhite) continue;
    /* key background */
    const pressed = rt.gutterPressed === note;
    g.fillStyle = pressed ? '#00e5ff' : 'rgba(255,255,255,0.95)';
    g.fillRect(gutterX, y, GUTTER_W, G.rh - 1);
    g.strokeStyle = 'rgba(0,0,0,0.3)'; g.lineWidth = 0.5;
    g.strokeRect(gutterX, y, GUTTER_W, G.rh - 1);
    /* octave label on C keys */
    if (pc === 0) {
      g.fillStyle = pressed ? '#000' : 'rgba(0,0,0,0.7)';
      g.font = '500 11px system-ui, sans-serif'; g.textAlign = 'left';
      g.fillText(`C${Math.floor(note / 12) - 1}`, gutterX + 4, y + G.rh / 2);
    }
  }
  /* black keys */
  for (let r = 0; r < G.R; r++) {
    const y = G.gy0 + (G.R - 1 - r) * G.rh;
    const note = expRowNote(b, rt, r);
    const pc = note % 12;
    const isWhite = ![1, 3, 6, 8, 10].includes(pc);
    if (isWhite) continue;
    const pressed = rt.gutterPressed === note;
    g.fillStyle = pressed ? '#00e5ff' : '#1a1a1a';
    const bw = GUTTER_W * 0.6;
    const bh = G.rh * 0.7;
    g.fillRect(gutterX + (GUTTER_W - bw) / 2, y, bw, bh);
  }
  g.restore();
}

const cyc = (list, v) => list[(list.findIndex(x => Math.abs(x - v) < 1e-6) + 1) % list.length];

function chipAction(b, rt, c) {
  const s = rt.seq;
  if (c.id === 'len') s.setLength(LENGTHS[(LENGTHS.indexOf(s.len) + 1) % LENGTHS.length]);
  else if (c.id === 'root') s.root = (s.root + 1) % 12;
  else if (c.id === 'scale') { const ks = Object.keys(SCALES); s.scale = ks[(ks.indexOf(s.scale) + 1) % ks.length]; }
  else if (c.id === 'odn' || c.id === 'oup') b.data.base = Math.max(0, Math.min(6, base(b) + (c.id === 'oup' ? 1 : -1)));
  else if (c.id.startsWith('page')) { b.data.page = +c.id.slice(4); b.data.follow = false; }
  else if (c.id === 'chord') { b.data.chordMode = !b.data.chordMode; changed(); return; }
  else if (c.id === 'follow') b.data.follow = b.data.follow === false;
  else if (c.id === 'aid') { b.data.aid = b.data.aid === false; changed(); return; }
  else if (c.id === 'trip') {                                          // 8th triplets in the whole line: step 1 a third late, step 3 a third early; again: straight
    const on = s.steps.some(x => x.nudge);
    s.steps.forEach((x, k) => { if (on) delete x.nudge; else if (k % 4 === 1) x.nudge = 1 / 3; else if (k % 4 === 3) x.nudge = -1 / 3; });
  }
  else if (c.id === 'rotl') s.rotate(-1);
  else if (c.id === 'rotr') s.rotate(1);
  else if (c.id === 'trdn') s.transpose(-1);
  else if (c.id === 'trup') s.transpose(1);
  else if (c.id === 'dice' && regenerate(b, blocks.find(x => x.id === b.owner)?.type, Math.floor(shownBar(b, rt) / 4))) { rt.seq.setState(store.pattern(b.data.pat)); changed(); return; }
  else if (c.id === 'dice') {                                          // a new line: notes from the scale, mostly the root, some accents
    const n = SCALES[s.scale].notes.length;
    s.steps = s.steps.map((_, k) => { const r = Math.random(); return { ...emptyStep(rowNote(s.scale, s.root, base(b), r < 0.5 ? 0 : Math.floor(Math.random() * (n + 1)))), rest: Math.random() < 0.25 && k % 4 !== 0, accent: Math.random() < 0.2, slide: Math.random() < 0.15 }; });
  }
  else if (c.id === 'expand') {                                        // toggle expanded view
    if (pg.seq) pg.seqFocus = pg.seqFocus === b.id ? 0 : b.id;
    else toggleFull(b);
    return;
  }
  else if (c.id === 'lanes') {                                         // toggle strips drawer (expanded only)
    b.data.drawer = b.data.drawer === false;
    changed(); return;
  }
  keep(b, rt);
}

/* the cell, or strip, under a point: { k (step in the line), row | strip } */
function hit(b, rt, G, e) {
  if (e.x < G.x0 || e.x >= G.x0 + G.w || e.y < G.gy0) return null;
  const k = page(b, rt) * PAGE + Math.min(PAGE - 1, Math.floor((e.x - G.x0) / G.cw));
  if (e.y >= G.sy) { const i = Math.floor((e.y - G.sy) / STRIP_H); return i < STRIPS.length ? { k, strip: i } : null; }
  if (e.y >= G.sy - 4) return null;
  return { k, row: Math.max(0, Math.min(G.R - 1, G.R - 1 - Math.floor((e.y - G.gy0) / G.rh))) };
}

function apply(b, rt, h, mode) {
  const s = rt.seq, st = s.steps[h.k];
  const isExp = h.isExp ?? expanded(b);
  if (h.strip === undefined) {
    if (mode.kind === 'clear') st.rest = true;
    else {
      st.rest = false;
      st.note = isExp ? expRowNote(b, rt, h.row) : rowNote(s.scale, s.root, base(b), h.row);
      const key = h.k + ':' + st.note;
      if (rt.heard1 !== key) { rt.heard1 = key; audition(b, rt, st); }      // painting across rows sounds each new note once
    }
  } else if (!st.rest) {
    if (h.strip === 0) st.accent = mode.value; else if (h.strip === 1) st.slide = mode.value;
    else if (h.strip === 2) st.gate = mode.value; else if (h.strip === 3) st.prob = mode.value;
    else if (h.strip === 4) { if (mode.value) st.nudge = mode.value; else delete st.nudge; }
    else if (mode.value) st.seventh = true; else delete st.seventh;
  }
}

/* a step heard at once while the transport is stopped (setting a note, picking a chord): the target instrument is started
   and plays it for a third of a second; a running transport plays the step itself. force=true sounds even while playing. */
async function audition(b, rt, st, force = false) {
  if (!force && (rt.seq.running || st.rest)) return;
  const a = target(b) || blocks.find(PLAYABLE);
  if (!a) return;
  const be = instrumentOf(a);
  await be.start();
  const rack = be.rack;
  if (!rack) return;
  const t = rack.ctx.currentTime + 0.02;
  for (const mod of rack.mods) if (mod.type === 'vco') rack.vcoNote(mod, t, st.note, { accent: st.accent, slide: false, long: false, gate: st.gate ?? 0.6, seventh: !!st.seventh, chord: st.chord }, false, 0.35);
}

/* the chord editor on step k: what it changes is stored at once; it sounds the chord on the target at the same time */
function openChordEditor(b, rt, k) {
  const st = rt.seq.steps[k];
  chordEditor.open(b, st, { commit: () => keep(b, rt), audition: x => audition(b, rt, x) });
}

function pointer(b, e) {
  const rt = runtime(b), s = rt.seq, G = geom(b, rt);
  const isExp = expanded(b);
  if (e.type === 'down') setLastPane(b);
  if (chordEditor.pointer(b, e)) return;

  /* gutter hit in expanded view */
  if (isExp && e.x >= b.x && e.x < b.x + GUTTER_W && e.y >= G.gy0 && e.y < G.gy0 + G.R * G.rh) {
    const r = G.R - 1 - Math.floor((e.y - G.gy0) / G.rh);      // r = 0 is the bottom row
    const note = expRowNote(b, rt, r);
    const touch = { gutter: true, note };
    if (e.type === 'down') {
      rt.gutterPressed = note;
      audition(b, rt, { note, accent: false, gate: 0.6, rest: false }, true);
      rt.touches.set(e.id, touch);
    } else if (e.type === 'move') {
      const existing = rt.touches.get(e.id);
      if (existing && existing.gutter && existing.note !== note) {
        rt.gutterPressed = note;
        audition(b, rt, { note, accent: false, gate: 0.6, rest: false }, true);
        existing.note = note;
      }
    } else {
      rt.gutterPressed = null;
      rt.touches.delete(e.id);
    }
    return;
  }

  if (e.type === 'down') {
    const c = rt.chips.find(c => e.x >= c.x && e.x < c.x + c.w && e.y >= c.y && e.y < c.y + c.h);
    if (c) { chipAction(b, rt, c); return; }
    const h = hit(b, rt, G, e);
    if (!h) return;
    if (b.data.chordMode && h.strip === undefined) { openChordEditor(b, rt, h.k); return; }
    const st = s.steps[h.k];
    let mode;
    if (h.strip === undefined) {
      if (isExp) {
        mode = !st.rest && expNoteRow(b, rt, st.note) === h.row ? { kind: 'clear' } : { kind: 'set' };
      } else {
        mode = !st.rest && noteRow(s.scale, s.root, base(b), st.note) === h.row ? { kind: 'clear' } : { kind: 'set' };
      }
    } else {
      mode = { kind: 'strip', value: h.strip === 0 ? !st.accent : h.strip === 1 ? !st.slide : h.strip === 2 ? cyc(GATES, st.gate) : h.strip === 3 ? cyc(PROBS, st.prob) : h.strip === 4 ? cyc(NUDGES, st.nudge || 0) : !st.seventh };
    }
    rt.touches.set(e.id, { mode, strip: h.strip, isExp });
    apply(b, rt, h, mode); keep(b, rt);
  } else if (e.type === 'move') {
    const t = rt.touches.get(e.id);
    if (!t) return;
    const h = hit(b, rt, G, e);
    if (!h || (t.strip !== undefined) !== (h.strip !== undefined) || (t.strip !== undefined && t.strip !== h.strip)) return;
    apply(b, rt, h, t.mode); keep(b, rt);
  } else { rt.touches.delete(e.id); rt.heard1 = null; }
}

registerBlock('melody', {
  kind: 'pane', hidden: true, label: 'Melody sequencer', cells: { w: 8, h: 4 }, min: { w: 6, h: 3 }, resize: 'free',
  init: () => ({ target: null, pat: null, base: 2, page: 0, follow: true }),
  copy: d => { d.pat = store.clonePattern(d.pat); },
  remove(b) { const rt = rts.get(b); if (rt) { if (rt.seq.rack) rt.seq.stop(); running.delete(rt); rt.leave(); } },
  draw, pointer,
});

/* track the last melody pane touched, for the F key */
let lastPane = null;
export const setLastPane = b => { lastPane = b; };
export const collapse = () => {
  if (pg.seq) pg.seqFocus = 0;
  else pg.full = 0;
};

/* expands the last melody pane touched, or leaves the expanded view */
export const toggleExpand = () => { if (lastPane) { if (pg.seq) pg.seqFocus = pg.seqFocus === lastPane.id ? 0 : lastPane.id; else toggleFull(lastPane); } };

