/* waterfall view geometry: pitch on X (low to high), time on Y (future at top, falling down).
 *
 * ```js
 * const G = waterfallGeom(x, y, w, h, kbH);   // geometry for the pane
 * const col = colOfNote(G, note);              // column index (0..36) for a MIDI note
 * const note = noteOfCol(G, col);              // MIDI note at column
 * const y = stepY(G, k, pos, len);             // Y of step k's bottom edge
 * const k = stepAtY(G, y, pos, len);           // step index at Y
 * const { first, last } = visibleSteps(pos, len); // visible step range (16 steps)
 * ```
 *
 * Orientation: columns 0..36 map to notes expBaseNote .. expBaseNote+36. Column 0 is lowest note (leftmost).
 * Rows: Y grows downward. stepY gives the bottom edge of a step's bar. Future steps have smaller Y (higher up).
 */

import { expBaseNote, EXP_ROWS } from './blocks/melody.js';

/* the waterfall geometry for a pane of width w and height h, with keyboard height kbH */
export function waterfallGeom(x, y, w, h, kbH = 96) {
  const cols = EXP_ROWS;                             // 37 columns, one per semitone
  const colW = w / cols;
  const strikeY = y + h - kbH;                       // strike line is the top of the keyboard
  const fallH = strikeY - y;                         // fall area height
  const stepH = fallH / 16;                          // 16 steps visible
  return { x, y, w, h, kbH, cols, colW, strikeY, fallH, stepH };
}

/* the lowest note shown in the waterfall (same as expanded grid) */
export function wfBaseNote(b) {
  return expBaseNote(b);
}

/* column index (0 = leftmost = lowest note) for a MIDI note */
export function colOfNote(G, note) {
  const base = wfBaseNote({});
  return note - base;
}

/* MIDI note at column (0..36) */
export function noteOfCol(G, col) {
  const base = wfBaseNote({});
  return base + col;
}

/* Y coordinate of step k's bottom edge.
 * pos: the playing position in steps (running: fractional; stopped: page start).
 * len: pattern length (rt.seq.len).
 * step k wraps by len. Future steps (k > pos) have smaller Y (above the strike line).
 */
export function stepY(G, k, pos, len) {
  const kk = ((k % len) + len) % len;
  const pp = ((pos % len) + len) % len;
  /* distance from pos in [0, len) steps */
  const diff = kk - pp;
  /* wrap the diff to the visible window of 16 steps: show 16 steps centered on pos */
  let d = diff;
  while (d < -15) d += len;
  while (d > 0) d -= len;
  /* Y = strikeY - (pos - k) * stepH = strikeY + d * stepH (d is negative for future steps) */
  return G.strikeY + d * G.stepH;
}

/* inverse: step index at Y (for hit testing) */
export function stepAtY(G, y, pos, len) {
  const d = (y - G.strikeY) / G.stepH;
  const k = Math.round(pos - d);
  return ((k % len) + len) % len;
}

/* the visible step range: 16 steps ending at the strike line (pos at the bottom) */
export function visibleSteps(pos, len) {
  const first = Math.floor(pos) - 15;
  const last = Math.floor(pos);
  return { first, last, len };
}

/* helper: is a column a white key? */
export function isWhiteCol(col) {
  const pc = ((col % 12) + 12) % 12;
  return ![1, 3, 6, 8, 10].includes(pc);
}

/* helper: is a column a C (for octave labels) */
export function isCCol(col) {
  return ((col % 12) + 12) % 12 === 0;
}

/* waterfall geometry tests (plain node) */

import { waterfallGeom, colOfNote, noteOfCol, stepY, stepAtY, visibleSteps, isWhiteCol, isCCol } from '../app/waterfall.js';
import { expBaseNote } from '../app/blocks/melody.js';

const G = waterfallGeom(0, 0, 370, 600, 100); // 370 = 37 * 10, easy colW = 10
const base = expBaseNote({ data: { base: 2 } }); // C3 = 48

console.log('base note:', base);
console.log('EXP_ROWS:', 37);

let pass = 0, fail = 0;
const ok = (cond, msg) => { if (cond) { pass++; console.log('  ✓', msg); } else { fail++; console.log('  ✗', msg); } };

/* lowest note is leftmost column (col 0) */
ok(colOfNote(G, base) === 0, 'lowest note maps to column 0');
ok(noteOfCol(G, 0) === base, 'column 0 maps to lowest note');
ok(noteOfCol(G, 36) === base + 36, 'column 36 maps to highest note');

/* round trip note -> col -> note for all 37 semitones */
for (let c = 0; c < 37; c++) {
  const n = noteOfCol(G, c);
  ok(colOfNote(G, n) === c, `round trip col ${c} -> note ${n} -> col ${colOfNote(G, n)}`);
}

/* stepY/stepAtY round trip */
const len = 64;
for (const pos of [0, 15, 16, 17, 31, 32, 33, 47, 48, 49, 63]) {
  for (const k of [pos - 15, pos - 8, pos - 1, pos, pos + 1, pos + 8, pos + 15, pos + 16]) {
    const y = stepY(G, k, pos, len);
    const k2 = stepAtY(G, y, pos, len);
    ok(k2 === ((k % len) + len) % len, `stepY/stepAtY pos=${pos} k=${k} -> ${k2}`);
  }
}

/* wrap at len: step k and k+len have same Y */
const pos = 10;
const y0 = stepY(G, 0, pos, len);
const ylen = stepY(G, len, pos, len);
ok(Math.abs(y0 - ylen) < 0.001, 'step k and k+len have same Y');

/* pos = page start when stopped: page 0 -> pos = 0 */
const page0 = 0 * 16;
const yStep0 = stepY(G, 0, page0, len);
ok(Math.abs(yStep0 - G.strikeY) < 0.001, 'step 0 at page 0 is at strikeY');
const yStep15 = stepY(G, 15, page0, len);
ok(yStep15 < G.strikeY, 'step 15 is above strikeY');

/* visibleSteps returns 16 steps ending at pos */
const vs = visibleSteps(pos, len);
ok(vs.first === pos - 15, 'visibleSteps.first = pos - 15');
ok(vs.last === pos, 'visibleSteps.last = pos');

/* white key detection */
const whiteCols = [0, 2, 4, 5, 7, 9, 11, 12, 14, 16, 17, 19, 21, 23, 24, 26, 28, 29, 31, 33, 35, 36];
for (let c = 0; c < 37; c++) {
  ok(isWhiteCol(c) === whiteCols.includes(c), `isWhiteCol(${c}) = ${isWhiteCol(c)}`);
}

/* C columns: 0, 12, 24, 36 */
for (let c = 0; c < 37; c++) {
  ok(isCCol(c) === (c % 12 === 0), `isCCol(${c}) = ${isCCol(c)}`);
}

console.log('\nPassed:', pass, 'Failed:', fail);
if (fail > 0) process.exit(1);

