/* waterfall geometry tests (plain node) */

import { waterfallGeom, colOfNote, noteOfCol, stepY, stepAtY, visibleSteps, isWhiteCol, isCCol, wfBaseNote } from '../app/waterfall.js';

const G = waterfallGeom(0, 0, 370, 600, 100); // 370 = 37 * 10, easy colW = 10
const b = { data: { base: 2 } }; // block with base = 2 -> C3 = 48
const base = wfBaseNote(b);

