/* Y coordinate of step k's bottom edge.
 * pos: the playing position in steps (running: fractional; stopped: page start).
 * len: pattern length (rt.seq.len).
 * step k wraps by len. Future steps (k > pos) have smaller Y (above the strike line).
 */
export function stepY(G, k, pos, len) {
  const kk = ((k % len) + len) % len;
  const pp = ((pos % len) + len) % len;
  /* distance from pos in [0, len) steps */
  const diff = kk - pp;
  /* wrap the diff to the visible window of 16 steps: show 16 steps centered on pos */
  let d = diff;
  while (d < -15) d += len;
  while (d > 0) d -= len;
  /* Y = strikeY - (pos - k) * stepH = strikeY + d * stepH (d is negative for future steps) */
  return G.strikeY + d * G.stepH;
}

/* inverse: step index at Y (for hit testing) */
export function stepAtY(G, y, pos, len) {
  const d = (y - G.strikeY) / G.stepH;
  const k = Math.round(pos - d);
  return ((k % len) + len) % len;
}

