/* Y coordinate of step k's bottom edge.
 * pos: the playing position in steps (running: fractional; stopped: page start).
 * len: pattern length (rt.seq.len).
 * Future steps (k > pos) have smaller Y (above the strike line).
 * No wrapping of the diff - each loop iteration continues above the previous.
 */
export function stepY(G, k, pos, len) {
  return G.strikeY - (k - pos) * G.stepH;
}

/* inverse: step index at Y (for hit testing) */
export function stepAtY(G, y, pos, len) {
  const d = (G.strikeY - y) / G.stepH;
  const k = pos + d;
  return Math.round(k);
}

